\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',message; end if; end $$;
insert into auth.users(id) values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222'),('33333333-3333-4333-8333-333333333333');
insert into public.night_episodes(day,title,brief,answer,aliases,explanation,source,clues) values
((now() at time zone 'America/New_York')::date,'Test night','A fictional mystery with real clues.','Grand Central Terminal',array['Grand Central Terminal','Grand Central'],'The clock gives it away.','https://grandcentralterminal.com/what-to-see/','[{"kind":"message","text":"first"},{"kind":"receipt","text":"second"},{"kind":"note","text":"third"},{"kind":"dispatch","text":"fourth"}]');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.night_episodes','SELECT'),'answer table must not be readable');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.night_runs','UPDATE'),'clients must not edit scores');
select pg_temp.assert_true(not has_function_privilege('anon','public.night_play(text,text)','EXECUTE'),'guests cannot play ranked');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.assert_true(not (public.night_play('state','') ? 'answer'),'unfinished state hides answer');
select pg_temp.assert_true(jsonb_array_length(public.night_play('state','')->'clues')=1,'unrevealed clues stay private');
select pg_temp.assert_true((public.night_play('reveal','')->>'revealed')::int=2,'reveal adds one clue');
select pg_temp.assert_true((public.night_play('guess','wrong')->>'wrong')::int=1,'wrong guess increments once');
select pg_temp.assert_true((public.night_play('guess','grand CENTRAL!!!')->>'score')::int=700,'normalized answer and score computed server-side');
select pg_temp.assert_true((public.night_play('reveal','')->>'revealed')::int=2,'finished runs cannot change');
select pg_temp.assert_true(jsonb_array_length(public.night_play('state','')->'clues')=4,'finished players get all story evidence without losing score');
select pg_temp.assert_true((public.night_play('guess','wrong')->>'score')::int=700,'replayed finished move cannot change score');
select pg_temp.assert_true(jsonb_array_length(public.night_play('state','')->'guesses')=2,'finished replays do not append fictional guesses');
select pg_temp.assert_true(public.night_play('state','')->'guesses'->0->>'place'='wrong','the wrong guess is stored for the story');
select pg_temp.assert_true((public.night_play('state','')->'guesses'->0->>'clueCount')::int=2,'guess history records the clue count at that moment');
select pg_temp.assert_true((public.night_play('state','')->'guesses'->1->>'correct')::boolean,'correct ending is identified');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.night_story_generations','UPDATE'),'clients cannot reset their AI budget');
select pg_temp.assert_true((public.night_reserve_story_generation()->>'remaining')::int=4,'first AI request reserves one slot');
select public.night_reserve_story_generation();
select public.night_reserve_story_generation();
select public.night_reserve_story_generation();
select pg_temp.assert_true((public.night_reserve_story_generation()->>'remaining')::int=0,'five daily AI requests allowed');
select pg_temp.assert_true(public.night_reserve_story_generation() ? 'error','sixth AI request is rejected');
select pg_temp.assert_true((public.night_submit_story('My night',repeat('An eventful fictional night. ',5),'first_player')->>'success')::boolean,'first story publishes');
select pg_temp.assert_true(public.night_submit_story('Other title',repeat('A different fictional night. ',5),'first_player') ? 'error','duplicate story rejected');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.night_story_cases','SELECT'),'community case answers stay behind the play function');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.night_story_case_runs','UPDATE'),'clients cannot edit community case scores');
select pg_temp.assert_true(public.night_story_case_source((public.night_community((now() at time zone 'America/New_York')::date)->'stories'->0->>'id')::uuid)->>'body' like 'An eventful%','finished player can use the published story as generation source');
select pg_temp.assert_true((public.night_reserve_case_generation()->>'remaining')::int=2,'first community generation reserves one slot');
select pg_temp.assert_true((public.night_save_story_case((public.night_community((now() at time zone 'America/New_York')::date)->'stories'->0->>'id')::uuid,'{"title":"The echo knew","brief":"A missed train and an apology crossed the room.","answer":"Grand Central Terminal","aliases":["Grand Central Terminal","Grand Central"],"explanation":"The clock, train and opposite corners identify Grand Central Terminal.","clues":[{"kind":"message","time":"11:00 PM","label":"CHAT","text":"opposite corners"},{"kind":"receipt","time":"11:05 PM","label":"RECEIPT","text":"one missed train"},{"kind":"note","time":"11:10 PM","label":"NOTE","text":"meet under the clock"},{"kind":"dispatch","time":"11:15 PM","label":"SIGNAL","text":"forty-second street"}]}'::jsonb)->>'success')::boolean,'generated community case saves once');
select pg_temp.assert_true((public.night_community((now() at time zone 'America/New_York')::date)->'stories'->0->>'playable')::boolean,'community feed marks generated case playable');
select pg_temp.assert_true(not (public.night_story_case_play((public.night_community((now() at time zone 'America/New_York')::date)->'stories'->0->>'id')::uuid,'state','') ? 'answer'),'community case hides answer before completion');
select pg_temp.assert_true(jsonb_array_length(public.night_story_case_play((public.night_community((now() at time zone 'America/New_York')::date)->'stories'->0->>'id')::uuid,'state','')->'clues')=1,'community case starts with one clue');
select pg_temp.assert_true((public.night_story_case_play((public.night_community((now() at time zone 'America/New_York')::date)->'stories'->0->>'id')::uuid,'guess','grand CENTRAL!!!')->>'score')::int=1000,'community case answers normalize and score server-side');
select public.night_reserve_case_generation();
select pg_temp.assert_true((public.night_reserve_case_generation()->>'remaining')::int=0,'three community generations are allowed each day');
select pg_temp.assert_true(public.night_reserve_case_generation() ? 'error','fourth community generation is rejected');
select pg_temp.assert_true(public.night_vote((public.night_community((now() at time zone 'America/New_York')::date)->'stories'->0->>'id')::uuid) ? 'error','self voting rejected');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select pg_temp.assert_true(jsonb_array_length(public.night_community((now() at time zone 'America/New_York')::date)->'stories')=0,'unfinished player cannot read spoilers');
select pg_temp.assert_true(public.night_submit_story('Another night',repeat('A fictional account of events. ',5),'second_player') ? 'error','unfinished player cannot submit');
select public.night_play('state','');
select pg_temp.assert_true((public.night_play('giveup','')->>'score')::int=0,'giving up earns no deduction points');
select pg_temp.assert_true(public.night_submit_story('Another night',repeat('A fictional account of events. ',5),'FIRST_PLAYER') ? 'error','handle uniqueness is case insensitive');
select pg_temp.assert_true((public.night_submit_story('Another night',repeat('A fictional account of events. ',5),'second_player')->>'success')::boolean,'finished unsolved player can tell story');
select public.night_vote((select (s->>'id')::uuid from jsonb_array_elements(public.night_community((now() at time zone 'America/New_York')::date)->'stories') s where s->>'alias'='first_player'));
select public.night_vote((select (s->>'id')::uuid from jsonb_array_elements(public.night_community((now() at time zone 'America/New_York')::date)->'stories') s where s->>'alias'='first_player'));
select pg_temp.assert_true((select (l->>'points')::int=750 and (l->>'votes')::int=1 from jsonb_array_elements(public.night_community((now() at time zone 'America/New_York')::date)->'leaders') l where l->>'alias'='first_player'),'duplicate votes count once; vote adds 50');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select public.night_play('guess','Grand Central');
select public.night_submit_story('Third night',repeat('One more fictional account. ',5),'third_player');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select public.night_vote((select (s->>'id')::uuid from jsonb_array_elements(public.night_community((now() at time zone 'America/New_York')::date)->'stories') s where s->>'alias'='third_player'));
select pg_temp.assert_true((select (l->>'points')::int=700 and (l->>'votes')::int=0 from jsonb_array_elements(public.night_community((now() at time zone 'America/New_York')::date)->'leaders') l where l->>'alias'='first_player'),'moving vote removes former author points');
select pg_temp.assert_true((select (l->>'points')::int=1050 and (l->>'votes')::int=1 from jsonb_array_elements(public.night_community((now() at time zone 'America/New_York')::date)->'leaders') l where l->>'alias'='third_player'),'moving vote awards new author points');
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true(public.night_play('guess','Grand Central') ? 'error','null auth is rejected inside function');
select pg_temp.assert_true(public.night_reserve_story_generation() ? 'error','AI requests reject missing auth');
select pg_temp.assert_true(public.night_reserve_case_generation() ? 'error','community case generation rejects missing auth');
select pg_temp.assert_true(public.night_story_case_play('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','state','') ? 'error','community play rejects missing auth');
reset role;
-- Close voting by moving the episode into the past, without mutating timestamps globally.
insert into public.night_episodes select day-1,title,brief,answer,aliases,explanation,source,clues,created_at from public.night_episodes;
insert into public.night_runs(day,user_id,finished) values((now() at time zone 'America/New_York')::date-1,'11111111-1111-4111-8111-111111111111',true);
insert into public.night_stories(id,day,user_id,title,body) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(now() at time zone 'America/New_York')::date-1,'11111111-1111-4111-8111-111111111111','Old story',repeat('Old account of a fictional evening. ',4));
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select pg_temp.assert_true(public.night_vote('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa') ? 'error','voting closes for past nights');
select pg_temp.assert_true((select (l->>'points')::int=1050 from jsonb_array_elements(public.night_community((now() at time zone 'America/New_York')::date)->'dailyLeaders') l where l->>'alias'='third_player'),'daily leaderboard uses daily scores and votes');
select 'All database game checks passed.' as result;
rollback;
